from pathlib import Path
x=json.loads(Path('analysis/initial.json').read_text())
for f in x['findings']:
 o=f['outcome'].replace(chr(92)+chr(34),chr(34))
 print(f['id'], ' '.join(m.group(0).split(' (')[0] for m in re.finditer(r'(?:component\.go|analysis/_probe/\w+\.go):\d+', o)))
 for m in re.finditer(r'((?:component\.go|analysis/_probe/\w+\.go)):(\d+) \("(.*?)"\)', o):
  p,n,s=m.groups(); line=Path(p).read_text().splitlines()[int(n)-1]
  if s not in line:
   print('MISMATCH',f['id'],p,n,repr(s),repr(line))
